import type { Config } from './index.ts'

import * as Context from './context.ts'

export const run = async (config: Config) => {
  const ctx = Context.createContext(config)
  const args = config.argv ?? process.argv.slice(2)

  const stackNames = Object.keys(config.stacks)

  if (args.length === 0) return console.log(help())

  // Resolve target stack
  let stackName = args.length > 0 && config.stacks[args[0]!] ? (args.shift(), args[0]) : config.default
  if (!stackName && stackNames.length === 1) stackName = stackNames[0]
  if (!stackName || !config.stacks[stackName]) throw new Error(`Stack ${stackName} not found`)

  // Check for built-in command
  const cmd = commands[args[0] as keyof typeof commands]!
  if (cmd) {
    args.shift()
    throw new Error(`Command ${cmd} not yet implemented`)
  }

  // Store compose.json in scratch space
  const file = await Context.resolvePath(ctx, config.stacks[stackName]!)

  // Execute docker compose command
  return Context.execute(ctx, {
    bin: ctx.config.bin ?? 'docker',
    env: { ...process.env, ...(ctx.config.env ?? {}) },
    args: [...(ctx.config.defaultArgs ?? ['compose']), '-f', file, ...(ctx.config.argv ?? process.argv.slice(2))],
  })
}

const commands = {
  diff: {
    run: (_ctx: Context.Cx, _config: Context.ShellOptions) => {
      // return execute(ctx, {
      //   bin: config.bin,
      //   env: config.env,
      //   args: [...config.args, 'diff'],
      // })
    },
  },
}

const help = () => {
  throw new Error('Help not yet implemented')
}